for each step:
    a = eps-greedy(QA[s] + QB[s]);  s2, r, done = env.step(a)
    if coin(): a* = argmax QA[s2];  QA[s,a] += alpha*(r + gamma*QB[s2,a*] - QA[s,a])
    else:      a* = argmax QB[s2];  QB[s,a] += alpha*(r + gamma*QA[s2,a*] - QB[s,a])

for each episode:
    play with eps-greedy(Q), storing (s, a, r)
    G = 0
    for (s, a, r) in reversed(episode):
        G = r + gamma*G
        Q[s,a] += alpha*(G - Q[s,a])

for each step:
    if some action untried in s: a = that action
    else: a = argmax Q[s] + c*sqrt(log(N[s]) / N[s,:])
    r, s2 = env.step(a);  N[s,a] += 1
    Q[s,a] += (1/N[s,a]) * (r + gamma*max(Q[s2]) - Q[s,a])

for each rollout of N steps:
    a ~ Normal(mu(s), exp(log_std));  env.step(rescale(clip(a, -1, 1)))
    compute GAE advantages and returns
    for epoch in 1..K, for each minibatch:
        ratio = exp(logp_new(a) - logp_old(a))
        loss = -min(ratio*A, clip(ratio, 1-eps, 1+eps)*A) + c*(V - R)^2

for each step:
    x = sample prompts;  y_1..y_G ~ π_old(.|x);  R_i = verify(x, y_i)
    A_i = (R_i - mean(R)) / std(R)
